from functools import wraps
from taf.internal.robot_typecasts import to_boolean


def enforce_use_m2m_type(func):
    """
    Decorator that converts given value of use_m2m to boolean True or False. It's very useful for parameters that come
    from robotframework interace.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        if 'use_m2m' in dict(kwargs):
            kwargs['use_m2m'] = to_boolean(kwargs['use_m2m'])
        result = func(*args, **kwargs)
        return result
    return wrapper
